export type PlanObservation={area:"academic"|"sport"|"creative"|"leadership"|"extracurricular";activity:string;currentLevel:string;strengths:string;focus:string};
export type PlanInput={goal:string;periodWeeks:number;observations:PlanObservation[]};
/** Deterministic resilience fallback. Never claim this output was generated by an AI model. */
export function draftPlanTemplate(input:PlanInput){
 const areas=[...new Set(input.observations.map(x=>x.area))];
 return {
  title:"Learning and development plan — template",
  summary:"Provisional actions for the stated goal: "+input.goal.slice(0,300)+". Review this plan with a teacher, coach or guardian before use.",
  recommendations:input.observations.map(o=>({
   area:o.area,goal:"Develop "+o.activity.slice(0,100)+" through regular supported practice",
   steps:["Discuss the focus area with an educator or coach and agree on a manageable task.","Practise the task in short, appropriate sessions and note what changes.","Review progress and adjust the activity with the learner."],
   measure:"Record participation, feedback, and specific progress observations",reviewWeek:Math.min(input.periodWeeks,3)
  })),
  coachOrTeacherReview:"An authorised teacher or coach must verify every observation, confirm a safe age-appropriate workload and approve the next review date. This is a template, not an AI assessment."
 };
}
